/* global ObjC, $ */
// Adds accurate Korean lettering only; all scene artwork is generated by image_gen.
ObjC.import('AppKit');
ObjC.import('CoreText');
// eslint-disable-next-line @typescript-eslint/no-unused-vars
function run(argv) {
  const root=argv[0],base=argv[1];
  const image=$.NSImage.alloc.initWithContentsOfFile(base+'/discovery-art-r1.png');
  const W=image.size.width,H=image.size.height;
  $.CTFontManagerRegisterFontsForURL($.NSURL.fileURLWithPath(root+'/design/jango/emoticons/kakao-32/v18/fonts/Gaegu-Bold.ttf'),1,null);
  const text=[
    {speaker:'jango',lines:['두부,','내일까지예요.'],box:[126,142,398,165],size:66,lineHeight:78},
    {speaker:'person',lines:['맞다.','저걸 또 잊었네.'],box:[665,103,345,149],size:56,lineHeight:70},
  ];
  const bitmap=$.NSBitmapImageRep.alloc.initWithBitmapDataPlanesPixelsWidePixelsHighBitsPerSampleSamplesPerPixelHasAlphaIsPlanarColorSpaceNameBytesPerRowBitsPerPixel(null,W,H,8,4,true,false,$.NSDeviceRGBColorSpace,W*4,32);
  const context=$.NSGraphicsContext.graphicsContextWithBitmapImageRep(bitmap);
  void $.NSGraphicsContext.saveGraphicsState;$.NSGraphicsContext.setCurrentContext(context);
  for(const t of text){
    const [x,y,w,h]=t.box,a=$.NSMutableDictionary.alloc.init;
    a.setObjectForKey($.NSFont.fontWithNameSize('Gaegu-Bold',t.size),$.NSFontAttributeName);
    a.setObjectForKey($.NSColor.colorWithCalibratedRedGreenBlueAlpha(0.29,0.25,0.22,1),$.NSForegroundColorAttributeName);
    const m=t.lines.map(s=>$(s).sizeWithAttributes(a));
    if(m.some(s=>s.width>w)||(t.lines.length-1)*t.lineHeight+Math.max(...m.map(s=>s.height))>h)throw Error('Text overflow: '+t.speaker);
    t.measured=m.map(s=>({width:s.width,height:s.height}));
    t.lines.forEach((s,i)=>$(s).drawAtPointWithAttributes($.NSMakePoint(x+(w-m[i].width)/2,H-y-i*t.lineHeight-m[i].height),a));
  }
  void $.NSGraphicsContext.restoreGraphicsState;
  if(!bitmap.representationUsingTypeProperties($.NSPNGFileType,$({})).writeToFileAtomically(base+'/discovery-lettering-r1.png',true))throw Error('Layer write failed');
  $(JSON.stringify({width:W,height:H,text},null,2)+'\n').writeToFileAtomicallyEncodingError(base+'/typography-report.json',true,$.NSUTF8StringEncoding,null);
  return 'Korean dialogue layer rendered and measured.';
}
